fields.code:
# Validate a token (registry message, admin token required)
{
  "type": "validate_token",
  "admin_token": "$TOKEN",
  "token": "eyJhbGciOiJSUzI1NiI..."
}

# Response for a valid token
{
  "type": "validate_token_ok",
  "verified": true,
  "subject": "alice@example.com",
  "issuer": "https://login.example.com/"
}

# directory.json
{
  "entries": [
    {"external_id": "alice@example.com", "role": "admin", "display_name": "alice"},
    {"external_id": "bob@example.com", "role": "member"},
    {"external_id": "charlie@example.com", "disabled": true}
  ]
}

# Push it to network 3, removing members not in the listing
pilotctl extras directory-sync directory.json --network 3 --remove-unlisted

# Current state: members, mapped, unmapped, pre-assignments
pilotctl extras directory-status 3

# Inspect the dead letter queue (registry message)
{
  "type": "get_webhook_dlq",
  "admin_token": "$TOKEN"
}
